const dictionaries: Record<Language, Messages> = {
  ES: { ...english, ...spanish },
  EN: english,
  FR: { ...english, ...regional.FR },
  CA: { ...english, ...regional.CA },
  IT: { ...english, ...regional.IT },
};

type I18nValue = { language: Language; setLanguage: (language: Language) => void; t: (key: string, params?: Record<string, string | number>) => string };
const I18nContext = createContext<I18nValue | null>(null);

export function I18nProvider({ children }: { children: ReactNode }) {
  const [language, setLanguageState] = useState<Language>(() => {
    const stored = localStorage.getItem('tunnel-language')?.toUpperCase() as Language | undefined;
    return stored && stored in dictionaries ? stored : 'ES';
  });
  const setLanguage = (next: Language) => { setLanguageState(next); localStorage.setItem('tunnel-language', next); document.documentElement.lang = next.toLowerCase(); };
  const value = useMemo<I18nValue>(() => ({ language, setLanguage, t: (key, params = {}) => Object.entries(params).reduce((message, [name, value]) => message.replaceAll(`{{${name}}}`, String(value)), dictionaries[language][key] ?? english[key] ?? key) }), [language]);
  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n() {
  const context = useContext(I18nContext);
  if (!context) throw new Error('useI18n must be used within I18nProvider');
  return context;
}
